#!/usr/bin/env python3
"""Build static astrology pages from editable JSON. No third-party dependencies."""
import json
from html import escape as e
from pathlib import Path
from site_components import merchandise

ROOT = Path(__file__).resolve().parents[1]
SIGNS = json.loads((ROOT / 'data/astrology-signs.json').read_text())['signs']
READINGS = json.loads((ROOT / 'data/astrology-readings.json').read_text())
OUT = ROOT / 'astrology'

def image(key, alt='', cls='', eager=False):
    return f'<img class="{cls}" src="../assets/images/astrology/{key}.webp" alt="{e(alt)}" width="{900 if key in ["sun","moon","rising"] else 733}" height="{900 if key in ["sun","moon","rising"] else 1100}" loading="{"eager" if eager else "lazy"}" decoding="async">'

def page(title, description, body, active=''):
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111219"><meta name="description" content="{e(description)}"><title>{e(title)} | Crystaleye</title><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="astrology.css"><link rel="stylesheet" href="../assets/merchandise.css"><link rel="stylesheet" href="../assets/cyberpunk.css"><script src="../assets/site.js" defer></script><script type="module" src="astrology.js"></script></head>
<body><a class="skip-link" href="#main">Skip to content</a>
<header class="site-header wrap"><a class="brand" href="../index.html" aria-label="Crystaleye home"><svg class="brand-mark" viewBox="0 0 48 32" aria-hidden="true"><path d="M2 16Q24-10 46 16Q24 42 2 16Z"/><path d="m24 5 9 11-9 11-9-11Z"/><circle cx="24" cy="16" r="3"/></svg><span>crystaleye<span class="brand-dot">.</span></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav"><span>Menu</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 6h14M3 14h14"/></svg></button><nav id="site-nav" aria-label="Main navigation"><a href="index.html" {'aria-current="page"' if not active else ''}>Astrology</a><a href="index.html#signs">The signs</a><a href="index.html#find-your-signs">Your big three</a></nav><a class="header-cta" href="index.html#subscription">Daily, with a little depth →</a></header>
<main id="main">{body}{merchandise("../")}</main>
<footer class="site-footer wrap astro-footer"><a class="brand" href="../index.html">crystaleye<span class="brand-dot">.</span></a><nav aria-label="Footer"><a href="index.html">Astrology home</a><a href="index.html#signs">All twelve signs</a><a href="index.html#subscription">The daily email</a><a href="../numerology/index.html">Numerology</a><a href="../tarot/index.html">Tarot &amp; daily draws</a><a href="../shop/index.html">Books &amp; decks</a><a href="../index.html">Explore Crystaleye →</a></nav><p>Astrology is a symbolic tradition for reflection and entertainment, not a scientifically validated prediction method. Readings are editorial prompts, not live transit calculations. Your choices remain yours.</p></footer></body></html>'''

def subscription():
    return '''<section id="subscription" class="subscription-band section-space"><div class="wrap subscribe-layout"><div><p class="eyebrow">A little cosmic mail</p><h2>Three signs.<br>One daily <em>ritual.</em></h2><p class="section-copy">More than your Sun sign. A thoughtful daily email with a separate paragraph for your Sun, Moon, and rising, made for a few quiet minutes with yourself.</p><p class="price">$5.99 <span>CAD / month</span></p><p class="launch-pill">Coming soon · subscriptions are not open yet</p><a class="button button-gold" href="#email-preview">Preview your daily email →</a><p class="fine-print">No payment or email address is collected here. Checkout and email delivery will be connected later.</p></div><div class="cadence"><h3>A rhythm that follows you.</h3><ol><li><span>Every day</span><p>One paragraph for each of your three signs, with a free, cheeky one-line summary for every sign on this page.</p></li><li><span>Every Sunday</span><p>Longer paragraphs that look back on your week, making room for reflection before you begin again.</p></li><li><span>The first of the month</span><p>A month-ahead preview: themes to explore, intentions to set, and possibilities to approach with curiosity.</p></li><li><span>The last day of the month</span><p>A gentle challenge: what did you learn, how did you grow, and what will you do differently?</p></li></ol><p class="fine-print">When dates overlap, both additions are included. A Sunday that opens or closes a month gets both kinds of reflection.</p></div></div></section>'''

def preview():
    options=''.join(f'<option value="{s["slug"]}">{s["name"]}</option>' for s in SIGNS)
    selects=''.join(f'<label>{role} sign<select name="{role.lower()}" id="preview-{role.lower()}">{options.replace(f"value=\"{default}\"", f"value=\"{default}\" selected")}</select></label>' for role,default in [('Sun','aries'),('Moon','cancer'),('Rising','libra')])
    return f'''<section class="wrap section-space" id="email-preview"><div class="section-topline"><p class="eyebrow">Try the ritual</p><span class="section-aside">A preview. A little perspective.</span></div><div class="preview-heading"><h2>Your inbox,<br><em>in the stars.</em></h2><p class="section-copy">Choose signs you already know and explore an example edition. These starting selections are an example, not a calculated birth chart. The free one-liners above always show today’s edition.</p></div><form id="preview-form" class="preview-form" hidden><div class="preview-inputs">{selects}<label>Edition date<input id="preview-date" type="date" required min="1900-01-01" max="2199-12-31"></label></div><div class="preview-actions"><button class="button button-gold" type="submit">Build my preview →</button><div class="date-shortcuts" aria-label="Choose an example edition"><button type="button" data-edition="today">Today</button><button type="button" data-edition="sunday">Sunday</button><button type="button" data-edition="first">Month ahead</button><button type="button" data-edition="last">Month reflection</button></div></div><p class="fine-print">Your selections stay in this browser tab. No account, email address, payment, or birth details are needed.</p></form><noscript><p class="notice">Enable JavaScript to personalize this preview. The example below shows the format; the sign profiles and calculation guide work without it.</p></noscript><div class="email-sample" aria-live="polite" aria-atomic="true"><div class="email-masthead"><span>crystaleye.</span><span>Your daily perspective</span></div><p id="preview-status" class="email-date">Sample edition · example Sun Aries, Moon Cancer, rising Libra</p><h3 id="preview-theme">A little space for yourself.</h3><div id="preview-badges" class="edition-badges"></div><div id="preview-readings">{''.join(f'<article class="email-paragraph"><p class="eyebrow">{role} · {name}</p><p>{e(READINGS["readings"][name.lower()][0]["body"])}</p></article>' for role,name in [('Sun','Aries'),('Moon','Cancer'),('Rising','Libra')])}</div><p class="email-signoff">Take what resonates. Leave room for your own experience.<br><em>With a little wonder, Crystaleye.</em></p><p class="fine-print">This is an on-page preview, not an email subscription. These are date-based editorial readings, not forecasts calculated from current planetary positions.</p></div></section>'''

def hub():
    cards=[]
    for s in SIGNS:
        slug=s['slug'];attrs=s['attributes'];alt=f'{s["name"]} constellation in neon nebula artwork' if slug not in ['aries','taurus'] else ('Neon solar emblem' if slug=='aries' else 'Neon sunrise emblem')
        cards.append(f'''<article class="zodiac-card" data-element="{attrs['Element'].lower()}"><a class="card-art" href="{slug}.html" tabindex="-1" aria-hidden="true">{image(s['image'],'')}<span class="card-element">{e(attrs['Element'])} / {e(attrs['Modality'])}</span><span class="zodiac-glyph" aria-hidden="true">{s['glyph']}</span></a><div class="zodiac-card-copy"><p class="sign-dates">{e(attrs['Approximate dates'])}</p><h3><a href="{slug}.html">{s['name']} <span aria-hidden="true">→</span></a></h3><p class="daily-teaser" data-teaser="{slug}">{e(READINGS['readings'][slug][0]['teaser'])}</p><a class="profile-link" href="{slug}.html">Sun, Moon &amp; rising profile →</a></div></article>''')
    body=f'''<section class="astro-hero wrap"><div class="astro-hero-copy"><p class="eyebrow"><span class="tiny-star" aria-hidden="true">✧</span> Welcome to the astrology wing</p><h1>The sky has layers.<br>So do <em>you.</em></h1><p class="hero-description">Your drive. Your inner world. The way you meet life.<br>Get to know your Sun, Moon, and rising—and leave a little room for the unexpected.</p><div class="hero-actions"><a class="button button-gold" href="#signs">Find your sign →</a><a class="text-link" href="#find-your-signs">Meet your big three →</a></div><p class="hero-note">A little perspective, with a cosmic sense of humour.</p></div><div class="big-three-art" aria-label="Neon Sun, Moon, and sunrise artwork"><div class="hero-orbit" aria-hidden="true"></div><figure class="emblem sun-emblem">{image('sun','A luminous neon Sun emblem',eager=True)}<figcaption>Sun <span>Your spark</span></figcaption></figure><figure class="emblem moon-emblem">{image('moon','A luminous neon crescent Moon',eager=True)}<figcaption>Moon <span>Your inner world</span></figcaption></figure><figure class="emblem rising-emblem">{image('rising','A luminous neon sunrise',eager=True)}<figcaption>Rising <span>Your first hello</span></figcaption></figure></div></section>
<div class="astro-manifesto wrap"><span>Twelve signs</span><span aria-hidden="true">✧</span><span>Three ways to know yourself</span><span aria-hidden="true">✧</span><span>Always your own story</span></div>
<section id="signs" class="wrap section-space"><div class="section-topline"><p class="eyebrow">01 / The daily little nudge</p><p id="daily-date" class="section-aside">Sample readings · enable JavaScript for today’s edition</p></div><div class="signs-heading"><div><h2>A wink from<br><em>the universe.</em></h2><p class="section-copy">Your free daily one-liner: a cheeky taste of the longer reading. Follow your Sun, Moon, and rising for three angles on the day.</p></div><div class="filter-bar" id="element-filters" hidden aria-label="Filter signs by element">{''.join(f'<button type="button" data-element-filter="{v.lower()}" aria-pressed="{str(v=="All").lower()}">{v}</button>' for v in ['All','Fire','Earth','Air','Water'])}</div></div><p id="sign-count" class="fine-print" aria-live="polite">All 12 signs</p><div class="zodiac-grid">{''.join(cards)}</div><p class="fine-print">Approximate tropical Sun-sign dates vary slightly by year. These are symbolic editorial readings, not live transit predictions. The free line and the detailed preview use the same daily theme.</p></section>
<section id="find-your-signs" class="big-three-section section-space"><div class="wrap"><div class="section-topline"><p class="eyebrow">02 / More than your birthday</p><span class="section-aside">Three placements. One whole person.</span></div><h2>Meet your<br><em>big three.</em></h2><div class="placement-grid"><article>{image('sun','Neon Sun artwork')}<p class="eyebrow">The Sun</p><h3>What lights you up.</h3><p>Your Sun sign is traditionally read as identity, vitality, and the direction of conscious self-expression. It describes a central thread, rather than every part of who you are.</p><a class="text-link" href="#signs">Explore the Sun profiles →</a></article><article>{image('moon','Neon crescent Moon artwork')}<p class="eyebrow">The Moon</p><h3>What feels like home.</h3><p>Your Moon sign is traditionally linked with emotional habits, instinctive responses, and the care that helps you feel secure. It can illuminate the part of you that close companions get to know.</p><a class="text-link" href="#calculation">Find your Moon sign →</a></article><article>{image('rising','Neon sunrise artwork')}<p class="eyebrow">The rising sign</p><h3>How you meet the world.</h3><p>Your rising sign, or Ascendant, is the zodiac sign on the eastern horizon at birth. It is traditionally associated with first impressions, approach, and the starting point of a natal chart.</p><a class="text-link" href="#calculation">Find your rising sign →</a></article></div>
<div class="calculation-panel" id="calculation"><div><p class="eyebrow">Your chart, accurately</p><h3>How to find your<br>Moon &amp; rising.</h3><p>There is no reliable shortcut from your Sun sign. Use a natal-chart calculator with an ephemeris and historical time-zone data, then read the Moon and Ascendant labels.</p><a class="button button-outline" href="https://www.astro.com/horoscope" target="_blank" rel="noopener noreferrer">Open Astro.com’s chart tools →</a><p class="fine-print">An independent third-party site. Review its privacy terms before entering birth information. Crystaleye does not calculate or collect your birth details here.</p></div><ol class="chart-steps"><li><h4>Gather your birth details</h4><p>Use your full birth date, recorded local birth time, and birth city or coordinates. A birth record is preferable to a family estimate. Check whether the time was a.m. or p.m.</p></li><li><h4>Set the chart correctly</h4><p>Use the tropical zodiac to match these profiles. Confirm the location and historical time zone, including daylight saving where applicable; a reputable calculator converts the recorded time to UTC.</p></li><li><h4>Read your Moon placement</h4><p>The calculator looks up the Moon’s zodiac position at that instant. The Moon changes signs roughly every two to three days, so exact birth time matters near a boundary. Record the sign beside the Moon symbol.</p></li><li><h4>Read your Ascendant</h4><p>The calculator uses birth time and geographical location to find the eastern horizon’s intersection with the ecliptic. Find “ASC” or “Ascendant.” Rising signs change roughly every two hours on average, with substantial variation by latitude and sign.</p></li></ol><details class="birth-time-note"><summary>What if I do not know my birth time?</summary><p>A noon chart does not give a reliable rising sign. Leave the Ascendant unknown instead of guessing. For the Moon, compare its position across the whole possible birth-time range: if it changes signs, both are possible until you have better time information. Near a Sun-sign boundary, check the exact birth year and time as well. If the recorded time is uncertain, allow that uncertainty in the interpretation.</p></details><details class="birth-time-note"><summary>Are the house associations on these pages my actual houses?</summary><p>No. The numbered house associations in the profiles are a common modern symbolic analogy between the twelve signs and twelve houses. Signs and houses are distinct; your actual house placements depend on your natal chart and chosen house system. A rising-sign description here does not automatically place every planet in a particular house.</p></details></div></div></section>
{subscription()}{preview()}<section class="wrap closing"><p class="eyebrow">A chart is a conversation starter.</p><h2>You get to write<br><em>the rest of the story.</em></h2><a class="text-link" href="../index.html">Explore the rest of Crystaleye →</a></section>'''
    return page('Astrology — Your Sun, Moon & rising','Explore all twelve zodiac signs, free daily horoscope one-liners, Moon and rising guides, and Crystaleye’s upcoming $5.99 CAD monthly horoscope email.',body)

def sign_page(s,index):
    a=s['attributes'];slug=s['slug'];prev=SIGNS[(index-1)%12];nxt=SIGNS[(index+1)%12]
    attrs=''.join(f'<div><dt>{e(k)}</dt><dd>{e(v)}</dd></div>' for k,v in a.items())
    sections=''.join(f'<article class="profile-topic"><h3>{e(k)}</h3><p>{e(v)}</p></article>' for k,v in s['sections'].items() if k not in ['Personality','Reflection prompt'])
    matches=''.join(f'<article><p class="eyebrow">{label}</p><h3><a href="{s[key]["sign"].lower()}.html">{s[key]["sign"]} →</a></h3><p>{e(s[key]["explanation"])}</p></article>' for label,key in [('Suggested best mate','mate'),('Suggested best friend','friend')])
    body=f'''<div class="wrap breadcrumb"><a href="../index.html">Crystaleye</a><span>/</span><a href="index.html">Astrology</a><span>/</span><span aria-current="page">{s['name']}</span></div><section class="wrap sign-hero"><div><p class="eyebrow">{e(a['Element'])} / {e(a['Modality'])} / {e(a['Approximate dates'])}</p><h1>{s['name']}<span class="sign-hero-glyph" aria-hidden="true">{s['glyph']}</span></h1><p class="archetype">{s['archetype']}</p><p class="section-copy">{e(s['sections']['Personality'])}</p><nav class="profile-jumps" aria-label="On this profile"><a href="#sun">Sun</a><a href="#moon">Moon</a><a href="#rising">Rising</a><a href="#connections">Connections</a></nav></div><figure class="sign-hero-art">{image(s['image'],f'Neon {s["name"]} constellation artwork' if slug not in ['aries','taurus'] else f'Neon {"Sun" if slug=="aries" else "sunrise"} emblem',eager=True)}<figcaption>{'Constellation-inspired artwork. Tropical signs and astronomical constellations are distinct.' if slug not in ['aries','taurus'] else 'A supplied celestial emblem, used symbolically for this profile.'}</figcaption></figure></section>
<section class="wrap daily-strip"><div><p class="eyebrow">Your free daily horoscope</p><p class="daily-teaser" data-teaser="{slug}">{e(READINGS['readings'][slug][0]['teaser'])}</p><p id="daily-date" class="fine-print">Sample reading · enable JavaScript for today’s edition</p></div><a class="text-link" href="index.html?sun={slug}#email-preview">Read the longer preview →</a></section>
<div class="wrap profile-layout"><aside class="sign-facts"><p class="eyebrow">At a glance</p><dl>{attrs}</dl><p class="fine-print">Dates are approximate. House associations are symbolic analogies, not your actual chart placements.</p></aside><div class="profile-reading"><section id="sun" class="profile-section"><p class="eyebrow">01 / Your Sun in {s['name']}</p><h2>{s['archetype']}<em> within.</em></h2><p class="profile-intro">Read this section for your Sun sign: the identity, motivations, and conscious expression associated with {s['name']}. These themes describe a symbolic archetype, not a fixed personality assessment.</p><div class="profile-topics">{sections}</div><blockquote><p>{e(s['sections']['Reflection prompt'])}</p><cite>A question to carry with you</cite></blockquote></section><section id="moon" class="profile-section placement-reading"><div>{image('moon','', 'placement-emblem')}<p class="eyebrow">02 / Your Moon in {s['name']}</p></div><h2>Your inner <em>weather.</em></h2><p>{e(s['moon'])}</p><a class="text-link" href="index.html#calculation">How to find your Moon sign →</a></section><section id="rising" class="profile-section placement-reading"><div>{image('rising','','placement-emblem')}<p class="eyebrow">03 / {s['name']} rising</p></div><h2>Your first <em>hello.</em></h2><p>{e(s['rising'])}</p><a class="text-link" href="index.html#calculation">How to find your rising sign →</a></section><section id="connections" class="profile-section"><p class="eyebrow">04 / Good company</p><h2>A little <em>chemistry.</em></h2><p class="profile-intro">There is no single objectively “best” sign for love or friendship. These are playful starting points from common element-based astrology, not guarantees or reasons to rule someone out. Your full charts, preferences, communication, and lived relationship matter more than a Sun-sign pairing.</p><div class="match-grid">{matches}</div></section></div></div>
<section class="wrap sign-subscription"><div><p class="eyebrow">Your Sun is only the start</p><h2>Bring your whole<br><em>big three.</em></h2><p>A daily paragraph each for your Sun, Moon, and rising. Longer Sunday reflections, a month-opening preview, and a month-end growth challenge.</p></div><div><p class="price">$5.99 <span>CAD / month</span></p><p class="launch-pill">Coming soon · not accepting payments</p><a class="button button-gold" href="index.html?sun={slug}#email-preview">Preview your three signs →</a><a class="text-link" href="index.html#subscription">See the subscription details →</a></div></section><nav class="wrap sign-pagination" aria-label="More signs"><a href="{prev['slug']}.html">← {prev['name']}</a><a href="index.html#signs">All twelve signs</a><a href="{nxt['slug']}.html">{nxt['name']} →</a></nav>'''
    return page(f'{s["name"]} — Sun, Moon, rising & connections',f'Explore {s["name"]} as your Sun, Moon, or rising sign, with strengths, relationships, work, growth prompts, and suggested love and friendship matches.',body,slug)

def main():
    OUT.mkdir(exist_ok=True)
    (OUT/'index.html').write_text(hub())
    for i,s in enumerate(SIGNS): (OUT/f'{s["slug"]}.html').write_text(sign_page(s,i))
    payload={'signs':[{k:s[k] for k in ['slug','name','glyph','sections']} for s in SIGNS],**READINGS}
    (OUT/'reading-data.mjs').write_text('// Generated by scripts/build_astrology.py; edit data/astrology-*.json instead.\nexport default '+json.dumps(payload,ensure_ascii=False,indent=2)+';\n')
    print('Built astrology hub, 12 sign profiles, and shared reading data.')

if __name__=='__main__': main()
